"""Cross-document consistency: same SHA, consistent claims, no stale PR #40 red light."""
import pathlib
import re

DOCS = pathlib.Path(r"<USER_HOME>")
FILES = [
    "architecture-blueprint.md", "adr/001-incremental-integration.md",
    "invariants.md", "memory-design.md", "permission-model.md",
    "runtime-policy-catalog.md", "evaluation-table.md",
]
SHA = "252fe311d8d1483b5713de69b04ce2769c33f1dd"

print("=== baseline SHA consistency ===")
for f in FILES:
    t = (DOCS / f).read_text(encoding="utf-8")
    print(f"  {f:<42} SHA present: {SHA in t}")

print("\n=== stale / wrong claims ===")
PATTERNS = {
    "stale #40 red light": r"#40.*(红灯|red|fail).*当前|currently (failing|red).*#40",
    "claims T17 passed": r"T17\s*(passed|通过|met|满足)",
    "claims token cap exists": r"(token[- ]budget cap).{0,40}(implemented|exists)",
    "says AGENTS.md exists": r"`AGENTS\.md`\s*(exists|存在)",
}
for f in FILES:
    t = (DOCS / f).read_text(encoding="utf-8")
    for name, pat in PATTERNS.items():
        if re.search(pat, t, re.I):
            print(f"  !! {f}: {name}")

print("\n=== required negative statements present ===")
MUST = {
    "S6 stopped / T17 not satisfied": r"(development is stopped|S6 development is stopped)",
    "T17 not accepted": r"not accepted as satisfied",
    "skipped != passed": r"(skipped job is\s+not a passed job|`skipped`)",
    "not a token cap": r"characters?, not tokens|character budget, not a token",
}
bp = (DOCS / "architecture-blueprint.md").read_text(encoding="utf-8")
adr = (DOCS / "adr/001-incremental-integration.md").read_text(encoding="utf-8")
combo = "\n".join((DOCS / f).read_text(encoding="utf-8") for f in FILES)
for name, pat in MUST.items():
    print(f"  {'OK ' if re.search(pat, combo, re.I) else 'MISSING'} {name}")

print("\n=== S5 final state statement ===")
for f in FILES:
    t = (DOCS / f).read_text(encoding="utf-8")
    if "S5" in t and ("merged" in t.lower() or "merged" in t):
        for line in t.splitlines():
            if "S5" in line and "merge" in line.lower():
                print(f"  {f}: {line.strip()[:120]}")

print("\n=== internal cross-links among the seven ===")
for f in FILES:
    t = (DOCS / f).read_text(encoding="utf-8")
    links = set(re.findall(r"\]\(([a-zA-Z0-9_\-/]+\.md)(?:#[^)]*)?\)", t))
    print(f"  {f:<42} -> {sorted(links)}")
